from lib import *
S = SS('g37')
steps = [
    step("没有 profile 时,编译器的默认判断:score(一个较长的热点函数)cannot inline score: function too complex: cost 146 exceeds budget 80。程序里有五种工作负载(iface 接口调用、inline 直接调用较长的 score、both 两者结合、flate 压缩、regexp 匹配邮箱格式)。", t=tl(S(1)), mark=lidx(S(1), 'cannot inline score'), kv=KV([['score 的代价', '146'], ['默认预算', '80'], ['结论', '默认构建里 score 不会被内联']], ['结论'])),
    step("收集 CPU profile:把五种 mode 各跑一遍,每个 profile 只有 607–1567 字节,用 go tool pprof -proto 合并成 default.pgo(3295 字节)。go tool pprof -top:main.runIface 1420ms(50.35%)、main.score 610ms(21.63%)、regexp/syntax.(*Inst).MatchRunePos 200ms(7.09%)、main.runBoth 160ms(5.67%)。", t=tl(S(2)), done=lidx(S(2), 'mode=iface', 'mode=inline', 'mode=both', 'mode=flate', 'mode=regexp'), mark=lidx(S(2), '合并后的 default.pgo', 'main.runIface', 'main.score'), kv=KV([['profile 来源', '每种 mode 跑一遍的 CPU profile'], ['合并', 'go tool pprof -proto a b c > default.pgo(3295 字节)'], ['热点', 'runIface 50.35%、score 21.63%、regexp 的 MatchRunePos 7.09%']], ['合并'])),
    step("用 -pgo=default.pgo 重新编译,编译器改变了决定:score 变成 can inline score with cost 146(代价没变,预算被热点调高了),并且在两个热调用点被内联(main.go:46 与 59 的 inlining call to score);接口方法 Circle.Area、Square.Area、Tri.Area 也都被内联(<autogenerated>:1: inlining call to …Area)——热调用点上的接口调用被改成“先判断具体类型再直接调用”。", t=tl(S(3)), done=lidx(S(3), 'can inline score', 'inlining call to score'), mark=lidx(S(3), 'Circle.Area', 'Square.Area', 'Tri.Area'), kv=KV([['score(代价 146)', 'PGO 下可以内联:两个热调用点都内联了'], ['接口方法 Area', 'Circle、Square、Tri 的 Area 都被内联'], ['含义', '热点调用的预算与接口调用的去虚拟化由 profile 决定']], ['含义'])),
    step("运行时间(每种 mode 各跑 7 次,中位数):iface(n = 4 亿)基线 1423 ms、PGO 1422 ms(快 0.1%);inline(n = 1 亿)都是 353 ms;both 基线 507 ms、PGO 517 ms(慢 2.0%);flate 压缩 都是 81 ms;regexp 基线 471 ms、PGO 433 ms(快 8.1%)。二进制大小:基线 3239922 字节,PGO 3256354 字节。只有 regexp 这一项有明显收益。", t=tl(S(4)), done=lidx(S(4), '只有接口调用', '只有直接调用较长', 'compress/flate'), mark=lidx(S(4), '接口调用 + 较长的 score', 'regexp 匹配邮箱格式', '二进制大小'), b=bars([['iface(PGO 更快)', 0.1, '快 0.1%'], ['inline', 0.0, '0.0%'], ['both(PGO 更慢)', 2.0, '慢 2.0%'], ['flate', 0.0, '0.0%'], ['regexp(PGO 更快)', 8.1, '快 8.1%']], 8.1, done=[0, 1, 3, 4], mark=[2]), kv=KV([['iface', '1423 → 1422 ms(+0.1%)'], ['inline', '353 → 353 ms(0.0%)'], ['both', '507 → 517 ms(慢 2.0%)'], ['flate', '81 → 81 ms(0.0%)'], ['regexp', '471 → 433 ms(快 8.1%)']], ['regexp'])),
    step("-pgo=auto 是默认行为:main 包目录里放了 default.pgo,普通的 go build 就会用上,go version -m 的构建信息里能看到 build -pgo=<目录>/default.pgo;-pgo=off 构建出来的产物里没有这一项。", t=tl(S(5)), done=lidx(S(5), '默认 go build'), mark=lidx(S(5), '-pgo=off'), kv=KV([['go build(目录里有 default.pgo)', '自动使用,go version -m 里有 -pgo=…'], ['-pgo=off', '关闭,构建信息里没有 -pgo']], ['go build(目录里有 default.pgo)'])),
]
A = mkartg('g37', 37, 'Go,PGO,profile,内联,去虚拟化,真实验证,动画演示',
    '在 Go 1.27.1(arm64)上真实测 PGO:用五种工作负载的 CPU profile 合并成 default.pgo 重新编译,编译器把代价 146 的 score 在热调用点内联、把接口调用的热目标内联;但 5 种工作负载里只有 regexp 明显变快(471 → 433 ms,8.1%),接口调用、直接调用、compress/flate 几乎没变,接口加较长函数的组合反而慢 2.0%——PGO 不保证变快;-pgo=auto 的默认行为。',
    'PGO(profile 引导优化)据说能让程序快 2% 到 14%。这篇自己做一遍:收集 profile、重新编译、看编译器的决定改了什么,然后在五种工作负载上对照运行时间。结果不全是好消息,这正是值得记录的地方。',
    [('8.1%', 'regexp 匹配在 PGO 构建下的提升(471 → 433 ms)'), ('0% 与 -2.0%', '其它四种负载的结果:接口调用、直接调用、flate 几乎不变,接口加较长函数的组合慢了 2.0%'), ('146 → 可内联', 'score 的代价 146 超过默认预算 80,PGO 下在热调用点被内联')],
    [('没有 profile 时', '<p>默认构建下,<code>-gcflags=-m=2</code> 的诊断是:<code>cannot inline score: function too complex: cost 146 exceeds budget 80</code>——函数的内联代价 146,超过了默认预算 80,所以不会被内联。这是后面对照的起点。</p>'),
     ('收集与使用 profile', '<p>profile 就是普通的 CPU profile(<code>runtime/pprof</code> 或 <code>go test -cpuprofile</code> 产生),多个 profile 可以用 <code>go tool pprof -proto</code> 合并。命名为 <code>default.pgo</code> 放在 main 包目录里,<code>go build</code> 默认(<code>-pgo=auto</code>)就会使用;<code>-pgo=off</code> 关闭。这个实验里每个 profile 很小(几百字节到 1.5 KB)——工作负载只跑了不到几秒。</p>'),
     ('编译器改变了什么', '<p>从 <code>-m=2</code> 的诊断能直接看到:<code>score</code> 的代价仍是 146,但在 profile 里的热调用点上内联预算被放宽,所以被内联了;接口调用 <code>s.Area()</code> 的热目标也被内联(实现上是在调用点先判断具体类型再直接调用,这是我对“Circle.Area 等被内联”这一诊断的解释,没有读生成的汇编)。</p>'),
     ('结果:不保证更快', '<p>五种负载里只有 <code>regexp</code> 的匹配循环有明显提升(8.1%)。接口调用与直接调用的两个微基准几乎没变,<code>compress/flate</code> 也没变,而同时有接口调用与较长函数的组合反而慢了 2%。我没有去查慢的原因(代码布局、寄存器分配都有可能),只能说:<b>PGO 的收益取决于程序,需要拿自己的负载测</b>,官方给的“几个百分点”不是保证,微基准更容易得到 0。另外这些数字是 arm64 单机上的结果,二进制也略有变大。</p>'),
     ('默认行为', '<p>因为 <code>-pgo=auto</code> 是默认,往 main 包目录里放一个 <code>default.pgo</code>,所有人构建的结果都会变——所以有这个文件时,要把它当作构建输入对待(纳入版本控制、定期更新),并在 CI 里确认没有性能退化。</p>')],
    steps,
    [ENV_G + '。基准是自己写的 5 种负载(带 -mode 参数的同一个程序);每种 mode 各跑 7 次取中位数;profile 来自基线构建的 runtime/pprof CPU profile,用 go tool pprof -proto 合并;编译器的决定来自 -gcflags=-m=2',
     '没有验证:更大、更真实的服务端程序上的收益、profile 的质量(采样时长、负载代表性)对结果的影响、PGO 构建的编译时间、慢 2.0% 的原因、PGO 在 amd64 上的结果、profile 随代码演进过期后的表现'],
    'PGO')
